INSERT INTO "public"."feed_items" ("id", "created_at", "updated_at", "title", "content", "url", "type", "status", "author_id", "sent_at", "organization_id", "poll_config", "is_public", "working_group_id") VALUES
	('674d6e12-f2a7-4db2-b087-be8df6294217', '2026-01-16 16:27:41.554176+00', '2026-01-16 16:28:00.305+00', 'sdfsaf', '<p>asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;as<span style="color: rgb(230, 0, 0);">d&nbsp;</span><em style="color: rgb(230, 0, 0);">sa&nbsp;d</em><span style="color: rgb(230, 0, 0);">as&nbsp;sad&nbsp;sa&nbsp;asd</span><strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;asd<strong>&nbsp;</strong>sd&nbsp;s<strong>ad&nbsp;as&nbsp;d</strong>d&nbsp;asd&nbsp;<em>sa&nbsp;d</em>as&nbsp;sad&nbsp;sa&nbsp;</p>', NULL, 'article', 'approved', '25071048-c449-4a60-b64b-e133f8003435', NULL, 'a9501361-b5cd-4a53-951a-bf639be85a4e', NULL, true, NULL),
	('4f07974d-85df-46b0-8af3-486c4edcfaa6', '2026-01-19 17:42:20.451986+00', '2026-01-19 17:43:02.789+00', 'wat auch immer', '<h1><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Zertifikats-Konflikt&nbsp;bei&nbsp;Mandanten-Deployments&nbsp;-&nbsp;Lösung</strong></h1><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Problembeschreibung</span></h2><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Bei&nbsp;neuen&nbsp;Mandanten-Deployments&nbsp;im&nbsp;Kubernetes-Cluster&nbsp;wird&nbsp;kein&nbsp;Zertifikat&nbsp;ausgestellt&nbsp;oder&nbsp;das&nbsp;Zertifikat&nbsp;ist&nbsp;nicht&nbsp;READY.&nbsp;Es&nbsp;existieren&nbsp;zwei&nbsp;Certificates,&nbsp;die&nbsp;beide&nbsp;denselben&nbsp;Secret&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;verwenden:</span></p><ul><li><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">{namespace}-certificate</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(manuell&nbsp;erstellt,&nbsp;soll&nbsp;beide&nbsp;Domains&nbsp;abdecken)&nbsp;-&nbsp;Status:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">False</code></li><li><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(automatisch&nbsp;erstellt,&nbsp;nur&nbsp;Mercure-Domain)&nbsp;-&nbsp;Status:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">True</code></li></ul><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Fehlermeldung:</strong></p><pre data-language="plain">

Secret was issued for &quot;cai-tls&quot;. If this message is not transient, you might have two conflicting Certificates pointing to the same secret.

</pre><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ursache</span></h2><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Das&nbsp;Problem&nbsp;entsteht&nbsp;durch&nbsp;einen&nbsp;Konflikt&nbsp;zwischen&nbsp;zwei&nbsp;Certificate-Ressourcen:</span></p><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Manuelles&nbsp;Certificate</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">{namespace}-certificate</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">):</span></li></ol><ul><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Wird&nbsp;von&nbsp;der&nbsp;Helm-Template&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">certficate.yaml</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;erstellt</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Soll&nbsp;beide&nbsp;Domains&nbsp;abdecken:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">{mandantName}.cai-digital.com</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;+&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">mrcr-{mandantName}.cai-digital.com</code></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Verwendet&nbsp;Secret:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code></li></ul><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Automatisches&nbsp;Certificate</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">):</span></li></ol><ul><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Wird&nbsp;automatisch&nbsp;von&nbsp;cert-manager&nbsp;erstellt</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Grund:&nbsp;Der&nbsp;Mercure-Ingress&nbsp;hat&nbsp;die&nbsp;Annotation&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cert-manager.io/cluster-issuer:&nbsp;letsencrypt-prod</code></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Deckt&nbsp;nur&nbsp;die&nbsp;Mercure-Domain&nbsp;ab:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">mrcr-{mandantName}.cai-digital.com</code></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Verwendet&nbsp;ebenfalls&nbsp;Secret:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code></li></ul><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Konflikt:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Beide&nbsp;Certificates&nbsp;versuchen&nbsp;denselben&nbsp;Secret&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;zu&nbsp;verwenden,&nbsp;was&nbsp;zu&nbsp;einem&nbsp;Konflikt&nbsp;führt.</span></p><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösung</span></h2><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Die&nbsp;cert-manager&nbsp;Annotation&nbsp;muss&nbsp;vom&nbsp;Mercure-Ingress&nbsp;entfernt&nbsp;werden,&nbsp;damit&nbsp;cert-manager&nbsp;kein&nbsp;automatisches&nbsp;Certificate&nbsp;erstellt.&nbsp;Nur&nbsp;das&nbsp;manuelle&nbsp;Certificate&nbsp;soll&nbsp;verwendet&nbsp;werden,&nbsp;das&nbsp;beide&nbsp;Domains&nbsp;abdeckt.</span></p><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Architektur&nbsp;nach&nbsp;der&nbsp;Lösung</span></h3><ul><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ein&nbsp;manuelles&nbsp;Certificate</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">{namespace}-certificate</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">)&nbsp;deckt&nbsp;beide&nbsp;Domains&nbsp;ab</span></li><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Beide&nbsp;Ingresses</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;(Webapp&nbsp;+&nbsp;Mercure)&nbsp;verwenden&nbsp;denselben&nbsp;Secret&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code></li><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Keine&nbsp;automatischen&nbsp;Certificates</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;von&nbsp;cert-manager&nbsp;(keine&nbsp;Annotation&nbsp;auf&nbsp;Ingresses)</span></li></ul><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Implementierung</span></h2><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Schritt&nbsp;1:&nbsp;Annotation&nbsp;aus&nbsp;PHP-Code&nbsp;entfernen</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Datei:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">application/src/Service/ClientDeploymentManagementService.php</code></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Entfernen:</strong></p><pre data-language="plain">

!$isLocal ? &quot;mercure.ingress.annotations.cert-manager\\.io/cluster-issuer=letsencrypt-prod&quot; : null,

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ergebnis:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Die&nbsp;Annotation&nbsp;wird&nbsp;beim&nbsp;Deployment&nbsp;nicht&nbsp;mehr&nbsp;gesetzt.</span></p><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Schritt&nbsp;2:&nbsp;Annotation&nbsp;aus&nbsp;Helm&nbsp;Values&nbsp;entfernen</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Datei:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">application/config/k8s/helm/cai/values.yaml</code></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Vorher:</strong></p><pre data-language="plain">

mercure:

ingress:

annotations:

kubernetes.io/ingress.class: nginx

cert-manager.io/cluster-issuer: letsencrypt-prod

nginx.ingress.kubernetes.io/backend-protocol: &quot;HTTP&quot;

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Nachher:</strong></p><pre data-language="plain">

mercure:

ingress:

annotations:

kubernetes.io/ingress.class: nginx

nginx.ingress.kubernetes.io/backend-protocol: &quot;HTTP&quot;

</pre><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Schritt&nbsp;3:&nbsp;Annotation&nbsp;aus&nbsp;Override-Values&nbsp;entfernen&nbsp;(falls&nbsp;vorhanden)</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Datei:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">k8s/helm-chart-overwritings/values.yaml</code></p><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Entferne&nbsp;die&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cert-manager.io/cluster-issuer</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Annotation&nbsp;aus&nbsp;den&nbsp;Mercure-Ingress-Annotations.</span></p><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Schritt&nbsp;4:&nbsp;Manuelles&nbsp;Certificate&nbsp;prüfen</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Datei:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">application/config/k8s/helm/cai/templates/01-shared/certficate.yaml</code></p><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Stelle&nbsp;sicher,&nbsp;dass&nbsp;das&nbsp;Certificate&nbsp;beide&nbsp;Domains&nbsp;abdeckt:</span></p><pre data-language="plain">

apiVersion: cert-manager.io/v1

kind: Certificate

metadata:

name: {{ .Values.namespace }}-certificate

namespace: {{ .Values.namespace }}

spec:

secretName: cai-tls

issuerRef:

name: letsencrypt-prod

kind: ClusterIssuer

dnsNames:

- &quot;{{ .Values.mandantName }}.cai-digital.com&quot;

- &quot;mrcr-{{ .Values.mandantName }}.cai-digital.com&quot;

</pre><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Verifikation</span></h2><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfen&nbsp;ob&nbsp;Annotation&nbsp;entfernt&nbsp;wurde</span></h3><pre data-language="plain">

# Prüfe Helm Values

helm get values {namespace} -n {namespace} | grep -A 10 &quot;mercure:&quot;

  

# Prüfe Ingress

kubectl get ingress {namespace}-mercure -n {namespace} -o yaml | grep &quot;cert-manager&quot;

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Erwartet:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Keine&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cert-manager.io/cluster-issuer</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Annotation</span></p><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfen&nbsp;ob&nbsp;nur&nbsp;ein&nbsp;Certificate&nbsp;existiert</span></h3><pre data-language="plain">

kubectl get certificates -n {namespace}

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Erwartet:</strong></p><ul><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Nur&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">{namespace}-certificate</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;sollte&nbsp;existieren</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Status:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">True</code></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Secret:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">cai-tls</code></li></ul><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfen&nbsp;ob&nbsp;beide&nbsp;Domains&nbsp;abgedeckt&nbsp;sind</span></h3><pre data-language="plain">

kubectl get certificate {namespace}-certificate -n {namespace} -o yaml | grep -A 3 &quot;dnsNames:&quot;

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Erwartet:</strong></p><pre data-language="plain">

dnsNames:

- {mandantName}.cai-digital.com

- mrcr-{mandantName}.cai-digital.com

</pre><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfen&nbsp;ob&nbsp;Secret&nbsp;beide&nbsp;Domains&nbsp;enthält</span></h3><pre data-language="plain">

kubectl get secret cai-tls -n {namespace} -o jsonpath=&#39;{.data.tls\.crt}&#39; | \

base64 -d | openssl x509 -noout -text | grep -A 1 &quot;Subject Alternative Name&quot;

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Erwartet:</strong></p><pre data-language="plain">

DNS:{mandantName}.cai-digital.com, DNS:mrcr-{mandantName}.cai-digital.com

</pre><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Bestehende&nbsp;Deployments&nbsp;reparieren</span></h2><p><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Falls&nbsp;ein&nbsp;Deployment&nbsp;bereits&nbsp;mit&nbsp;dem&nbsp;alten&nbsp;Code&nbsp;erstellt&nbsp;wurde:</span></p><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Annotation&nbsp;vom&nbsp;Ingress&nbsp;entfernen:</strong></li></ol><pre data-language="plain">

kubectl annotate ingress {namespace}-mercure -n {namespace} cert-manager.io/cluster-issuer-

</pre><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Automatisches&nbsp;Certificate&nbsp;löschen:</strong></li></ol><pre data-language="plain">

kubectl delete certificate cai-tls -n {namespace}

</pre><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Secret&nbsp;löschen&nbsp;(falls&nbsp;falsches&nbsp;Certificate):</strong></li></ol><pre data-language="plain">

kubectl delete secret cai-tls -n {namespace}

</pre><ol><li><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Warten&nbsp;bis&nbsp;manuelles&nbsp;Certificate&nbsp;READY&nbsp;ist:</strong></li></ol><pre data-language="plain">

kubectl get certificates -n {namespace} -w

</pre><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Zusammenfassung</span></h2><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Problem:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Zwei&nbsp;Certificates&nbsp;verwenden&nbsp;denselben&nbsp;Secret&nbsp;→&nbsp;Konflikt</span></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösung:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Annotation&nbsp;entfernen,&nbsp;damit&nbsp;nur&nbsp;das&nbsp;manuelle&nbsp;Certificate&nbsp;verwendet&nbsp;wird</span></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ergebnis:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Ein&nbsp;Certificate&nbsp;mit&nbsp;beiden&nbsp;Domains,&nbsp;beide&nbsp;Ingresses&nbsp;funktionieren</span></p><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Referenz:&nbsp;Funktionierendes&nbsp;Beispiel</span></h2><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Namespace:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">stage-4</code></p><pre data-language="plain">

kubectl get certificates -n stage-4

# NAME READY SECRET AGE

# stage-4-certificate True cai-tls 154d

  

kubectl get ingress -n stage-4

# NAME CLASS HOSTS ADDRESS PORTS AGE

# app-ingress nginx stage.cai-digital.com 141.95.96.198 80, 443 154d

# stage-4-mercure nginx mrcr-stage.cai-digital.com 141.95.96.198 80, 443 6d4h

</pre><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Hinweis:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Der&nbsp;Mercure-Ingress&nbsp;hat&nbsp;hier&nbsp;KEINE&nbsp;cert-manager&nbsp;Annotation.</span></p><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Checkliste&nbsp;für&nbsp;neue&nbsp;Deployments</span></h2><ul><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Annotation&nbsp;aus&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">ClientDeploymentManagementService.php</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;entfernt</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Annotation&nbsp;aus&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">values.yaml</code><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;entfernt</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Annotation&nbsp;aus&nbsp;Override-Values&nbsp;entfernt&nbsp;(falls&nbsp;vorhanden)</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Code&nbsp;committed&nbsp;und&nbsp;deployed</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Neues&nbsp;Deployment&nbsp;getestet</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Nur&nbsp;ein&nbsp;Certificate&nbsp;vorhanden&nbsp;(Status:&nbsp;True)</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Beide&nbsp;Domains&nbsp;im&nbsp;Certificate</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Beide&nbsp;Ingresses&nbsp;funktionieren</span></li></ul><h2><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Troubleshooting</span></h2><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Problem:&nbsp;Certificate&nbsp;bleibt&nbsp;im&nbsp;Status&nbsp;&quot;False&quot;</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ursache:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Secret&nbsp;ist&nbsp;noch&nbsp;vom&nbsp;alten&nbsp;Certificate&nbsp;belegt</span></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösung:</strong></p><pre data-language="plain">

kubectl delete secret cai-tls -n {namespace}

# Warten bis Certificate neu erstellt wird

</pre><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Problem:&nbsp;Annotation&nbsp;wird&nbsp;immer&nbsp;noch&nbsp;gesetzt</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ursache:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Code-Änderungen&nbsp;nicht&nbsp;deployed&nbsp;oder&nbsp;alte&nbsp;Values&nbsp;verwendet</span></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösung:</strong></p><ol><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfe&nbsp;ob&nbsp;Code-Änderungen&nbsp;committed&nbsp;sind</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfe&nbsp;ob&nbsp;neuer&nbsp;Code&nbsp;deployed&nbsp;wurde</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfe&nbsp;Helm&nbsp;Values:&nbsp;</span><code style="background-color: rgb(36, 36, 36); color: rgb(218, 218, 218);">helm&nbsp;get&nbsp;values&nbsp;{namespace}&nbsp;-n&nbsp;{namespace}</code></li></ol><h3><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Problem:&nbsp;Webapp&nbsp;funktioniert&nbsp;nicht&nbsp;(nur&nbsp;Mercure)</span></h3><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Ursache:</strong><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">&nbsp;Certificate&nbsp;deckt&nbsp;nur&nbsp;Mercure-Domain&nbsp;ab</span></p><p><strong style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösung:</strong></p><ol><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Prüfe&nbsp;Certificate&nbsp;DNS-Names</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Stelle&nbsp;sicher,&nbsp;dass&nbsp;beide&nbsp;Domains&nbsp;im&nbsp;Certificate&nbsp;sind</span></li><li><span style="background-color: rgb(30, 30, 30); color: rgb(218, 218, 218);">Lösche&nbsp;Secret&nbsp;und&nbsp;warte&nbsp;auf&nbsp;Neuerstellung</span></li></ol><p></p>', NULL, 'article', 'approved', 'cae97c36-c953-4b44-b3cc-7a08cc992fde', NULL, '6553b544-7514-41ef-85b5-28dc20b388f9', NULL, true, NULL),
